head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDDST70420";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_yearItems();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst70420.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("nowYear")) { pc.set("nowYear", $c.date.getServerDateTime("yyyy")); }
};

// 연도 선택 항목 — as-is 가 서버에서 그리던 범위를 화면에서 세운다(값 원천 = dma_pageContext.nowYear).

/**
 * @method
 * @name init_yearItems
 * @description 초기화 — year Items
 * @returns {void}
 * @hidden N
 */
scwin.init_yearItems = function () {
    const pc = $c.util.getComponent("dma_pageContext");
    const ny = Number(pc && pc.get ? pc.get("nowYear") : 0);
    if (!ny) { /* TODO Stage2: [sdd] 연도 선택 — ipt_nowYear 미충전(init_nowVars 앞에서 불렸다) */ return 0; }
    {
        const s = $c.util.getComponent("slc_year");
        if (!s || typeof s.addItem !== "function") { /* TODO Stage2: [sdd] 연도 선택 대상 부재:  "slc_year */ }
        else {
            if (typeof s.removeAll === "function") { s.removeAll(); }
            for (let i = 0; i <= 9; i++) {
                const y = String(ny - (i - (0)) * 1);
                s.addItem(y, y);
            }
            s.setValue(String(ny));
        }
    }
    return 1;
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.fnSearch();

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst70420.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst70420.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_findCompanyName_onclick
 * @description btn_findCompanyName 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_findCompanyName_onclick = function(e){
    try {
        Promise.resolve($c.win.openPopup('/ui/jsp/JLDFIL00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } }); return false;

} catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst70420.btn_findCompanyName_onclick' }); }
};

/**
 * @method
 * @name btn_searchCorpBasicInfo_onclick
 * @description btn_searchCorpBasicInfo 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_searchCorpBasicInfo_onclick = async function(e){
    try {
        await scwin.searchCorpBasicInfo(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst70420.btn_searchCorpBasicInfo_onclick' }); }
};

/**
 * @method
 * @name btn_fnDownload_onclick
 * @description btn_fnDownload 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnDownload_onclick = async function(e){
    try {
        await scwin.fnDownload(); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst70420.btn_fnDownload_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnDownload
 * @description fn Download 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnDownload = async function () {
    const sbmOptions = {
        id: "tx_fnDownload",
        method: "post",
        action: "/listinvstg/yearfinance.do",
        ref: "dma_fnDownloadReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/listinvstg/yearfinance.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('AKCKwd')))) {
                await scwin.searchCorpBasicInfo();
            }
        }
    }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchYearFinanceSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "yearfinance_sub");
    await scwin.tx_fnSearch_ajaxsubmit();
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).removeAll ? ($c.util.getComponent('contents')).removeAll() : (($c.util.getComponent('contents')) && ($c.util.getComponent('contents')).setValue ? ($c.util.getComponent('contents')).setValue('') : void 0)).append(data);
};

/**
 * @method
 * @name fnDownload
 * @description fn Download 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnDownload = async function () {
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    $("#searchForm").attr('onsubmit', '');
    $c.util.getComponent("dma_fnDownloadReq").set("method", "searchYearFinanceSub");
    $c.util.getComponent("dma_fnDownloadReq").set("forward", "yearfinancet_down");
    await scwin.tx_fnDownload();
    $("#searchForm").attr('onsubmit', 'return false;');
};

/**
 * @method
 * @name fnsearchKeyCode
 * @description fnsearch Key Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnsearchKeyCode = async function () {
    await scwin.searchCorpBasicInfo();
};

/**
 * @method
 * @name fnSearchCorpName
 * @description fn Search Corp Name 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpName = async function () {
    await scwin.searchCorpBasicInfo();
};

/**
 * @method
 * @name searchCorpBasicInfo
 * @description search Corp Basic Info 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCorpBasicInfo = async function () {
    $c.util.getComponent('ipt_isurCd').setValue("");
    $c.util.getComponent('ipt_kisComCd').setValue("");
    let cd_or_nm = $c.util.getComponent('AKCKwd').getValue(); if (cd_or_nm == null) { cd_or_nm = ''; }
    if (cd_or_nm == null || cd_or_nm === "") {
        await $c.win.alert("회사명 또는 종목코드를 입력해 주세요.");
        return;
    }
    $c.util.getComponent("dma_fnDownloadReq").set("searchCorpName", $c.util.getComponent('AKCKwd').getValue());
    Promise.resolve($c.win.openPopup('/ui/jsp/JLDFIL00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    if (items.length === 1) {
        await scwin.fnSetCorpBasicInfo(items[0]);
    } else {
        if (items.length > 1) {
            Promise.resolve($c.win.openPopup('/ui/jsp/JLDFIL00033.xml', { id: "pop_corp_std" }, { method: "loadInitPage" })).then(function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setCorpInfo).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setCorpInfo.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } });
    } else {
        await scwin.fnSetCorpBasicInfo(null);
    }
}
};

/**
 * @method
 * @name fnSetCorpBasicInfo
 * @description fn Set Corp Basic Info 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSetCorpBasicInfo = async function (items) {
    if (items == null) {
        const val = ($c.util.getComponent("dma_fnDownloadReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", "");
        $c.util.getComponent('AKCKwd').setValue("");
        $c.util.getComponent("AKCKwd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
    } else {
        const isurcd = items.isurcd;
        const kiscomcd = items.kiscomcd;
        const comabbr = items.comabbrv;
        $c.util.getComponent("dma_fnDownloadReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnDownloadReq").set("kisComCd", kiscomcd);
        $c.util.getComponent('AKCKwd').setValue(comabbr);
        await scwin.fnSearch();
    }
};

/**
 * @method
 * @name setCorpInfo
 * @description set Corp Info 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {String} ipt_kisComCd ipt_kisComCd
 * @param {String} ipt_repIsuSrtCd ipt_repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo = function (ipt_isurCd, ipt_kisComCd, ipt_repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo) {
    let str = "";
    str += "isurCd : " + ipt_isurCd + "\n";
    str += "kisComCd : " + ipt_kisComCd + "\n";
    str += "repIsuSrtCd : " + ipt_repIsuSrtCd + "\n";
    str += "comNm : " + comNm + "\n";
    str += "comAbbrv : " + comAbbrv + "\n";
    str += "isurSymbl : " + isurSymbl + "\n";
    str += "fssUnqNo : " + fssUnqNo + "\n";
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
    $c.util.getComponent('ipt_kisComCd').setValue(ipt_kisComCd);
};
